 const auto result=up::apply(manager,step.context);if(const auto* e=std::get_if<up::Error>(&result))throw std::runtime_error(c.name+": "+std::string(e->field));const auto& out=std::get<up::Output>(result);need(out.visited==step.record_calls.size(),"visited differs from real virtual calls");const bool gated=step.record_calls.empty()&&std::holds_alternative<wl::Index>(manager.head);need(out.clock_gated==gated,"clock gate differs from original calls");std::vector<U> expected_order;auto next=manager.head;while(auto i=std::get_if<wl::Index>(&next)){need(expected_order.size()<128,"input list cycle");expected_order.push_back(f::encode_link(next));next=manager.records[i->value].next;}if(!gated)need(expected_order==step.record_calls,"record dispatch order differs from linked source");
